mapper.select:
SELECT C.*,(SELECT CATE_VALUE FROM CATEGORY WHERE CATE_SEQ = C.COURSE_CATEGORY) AS CATE_VALUE
FROM COURSE C
WHERE MEMBER_NO=#{memberNo}

SELECT COUNT(*)
FROM COURSE_REVIEW
WHERE COURSE_SEQ = #{courseSeq}
  AND MEMBER_SEQ = #{memberSeq}
  AND REVIEW_DELETE_TIME IS NULL

SELECT *
FROM COURSE_PROGRESS
WHERE CURR_SEQ = #{currSeq}
AND MEMBER_SEQ = #{memberSeq}

SELECT S.*, C.*, P.*
FROM SECTION S
         LEFT JOIN CURRICULUM C ON S.SECTION_SEQ = C.SECTION_SEQ
         LEFT JOIN COURSE_PROGRESS P ON C.CURR_SEQ = P.CURR_SEQ AND P.MEMBER_SEQ = #{memberSeq}
WHERE S.COURSE_SEQ = #{courseSeq}
ORDER BY S.SECTION_ORDER, C.CURR_ORDER
